// Violates 1NF: repeating groups in a single column
// orders(id, customer, items) where items = 'book,pen,paper'

// 1NF: atomic values, no repeating groups
// orders(id, customer_id)
// order_items(order_id, item_id, quantity)

// Violates 2NF: partial dependency on composite key
// order_items(order_id, item_id, item_name, quantity)
// item_name depends only on item_id, not the full composite key

// 2NF: remove partial dependencies
// order_items(order_id, item_id, quantity)  -- depends on full key
// items(item_id, item_name, price)          -- item_name moved here

// Violates 3NF: transitive dependency
// employees(emp_id, dept_id, dept_name)
// dept_name depends on dept_id, not directly on emp_id

// 3NF: remove transitive dependencies
// employees(emp_id, dept_id)
// departments(dept_id, dept_name)

// BCNF: every determinant must be a candidate key
// teaching(student, subject, teacher)
// If teacher -> subject (a teacher teaches only one subject),
// teacher is a determinant but not a candidate key -- violates BCNF
// Solution: teacher(teacher, subject) + enrollment(student, teacher)

-- Simple junction table (composite primary key)
CREATE TABLE student_courses (
    student_id BIGINT REFERENCES students(id),
    course_id  BIGINT REFERENCES courses(id),
    PRIMARY KEY (student_id, course_id)
);

-- Rich junction table with its own attributes and surrogate PK
CREATE TABLE enrollments (
    id          BIGSERIAL PRIMARY KEY,
    student_id  BIGINT NOT NULL REFERENCES students(id),
    course_id   BIGINT NOT NULL REFERENCES courses(id),
    enrolled_at TIMESTAMP NOT NULL DEFAULT now(),
    grade       CHAR(2),
    UNIQUE (student_id, course_id)
);

// JPA: simple @ManyToMany mapping
@Entity
public class Student {
    @Id @GeneratedValue private Long id;
    private String name;

    @ManyToMany
    @JoinTable(
        name = "student_courses",
        joinColumns = @JoinColumn(name = "student_id"),
        inverseJoinColumns = @JoinColumn(name = "course_id")
    )
    private Set<Course> courses = new HashSet<>();
}

// JPA: rich junction as a dedicated @Entity (preferred when attributes exist)
@Entity
public class Enrollment {
    @Id @GeneratedValue private Long id;

    @ManyToOne
    @JoinColumn(name = "student_id")
    private Student student;

    @ManyToOne
    @JoinColumn(name = "course_id")
    private Course course;

    private LocalDateTime enrolledAt;
    private String grade;
}
